/* ===================== Shows list ===================== */
.shows-section { padding: 36px 24px 56px; }
.shows-title {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.5rem;
  margin: 0 0 22px;
}
.shows-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}
.show-item {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px;
  cursor: pointer;
  transition: border-color 0.12s ease, transform 0.12s ease;
  background: var(--paper);
}
.show-item:hover { border-color: var(--ink); transform: translateY(-2px); }
.show-item--tight { opacity: 0.55; }
.show-item--leg { border-color: var(--ok); border-width: 2px; }
.show-item--selected { border-color: var(--red); border-width: 2px; box-shadow: var(--shadow-soft); }
.show-genre {
  display: inline-block;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 700;
  color: var(--red);
  margin-bottom: 8px;
}
.show-name { font-weight: 800; font-size: 1.05rem; margin: 0 0 6px; }
.show-meta { color: var(--muted); font-size: 0.9rem; margin: 0 0 2px; }
.show-time { font-weight: 700; }

/* Map popup */
.popup-genre {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 700;
  color: var(--red);
}
.popup-title { font-weight: 800; font-size: 1rem; margin: 2px 0 4px; }
.popup-meta { color: var(--muted); font-size: 0.85rem; margin: 0; }

/* "You are here" marker */
.user-marker { background: transparent; border: none; }
.user-dot {
  display: block;
  width: 16px;
  height: 16px;
  margin: 2px;
  border-radius: 50%;
  background: var(--blue);
  border: 3px solid #fff;
  box-shadow: 0 0 0 0 rgba(108, 76, 241, 0.5);
  animation: userPulse 2s infinite;
}
@keyframes userPulse {
  0%   { box-shadow: 0 0 0 0 rgba(108, 76, 241, 0.45); }
  70%  { box-shadow: 0 0 0 14px rgba(108, 76, 241, 0); }
  100% { box-shadow: 0 0 0 0 rgba(108, 76, 241, 0); }
}

/* ===================== Footer ===================== */
.site-footer {
  background: var(--ink);
  color: #d9d9d9;
  padding: 48px 0;
  margin-top: 24px;
}
.footer-inner {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr auto;
  gap: 32px;
  align-items: start;
}
.logo--footer { color: var(--red); margin: 0 0 12px; }
.footer-tagline { max-width: 320px; margin: 0 0 16px; color: #cfcfcf; }
.footer-copy { color: #8c8c8c; font-size: 0.85rem; margin: 0; }
.footer-heading {
  color: var(--red);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-size: 0.82rem;
  margin: 4px 0 14px;
}
.footer-link {
  display: block;
  text-decoration: underline;
  color: #d9d9d9;
  margin-bottom: 10px;
  font-size: 0.92rem;
}
.footer-link:hover { color: #fff; }
.footer-actions { display: flex; gap: 10px; }

