.tip-perf {
  display: flex; align-items: center; gap: 7px;
  font-size: 0.78rem; color: var(--ink); font-variant-numeric: tabular-nums;
}
.tip-perf i { width: 12px; height: 10px; border-radius: 3px; flex: 0 0 auto; }
.tip-perf b { font-weight: 700; }
.tip-status { color: var(--muted); font-size: 0.72rem; }
/* The performance the plan picked, called out in the same gold as its mark. */
.tip-perf--planned .tip-status { color: #8a6d10; font-weight: 700; }
.tip-desc {
  margin: 9px 0 0; padding-top: 8px; border-top: 1px solid var(--line);
  font-size: 0.75rem; line-height: 1.5; color: var(--muted);
}
.tip-hint {
  margin: 8px 0 0; font-size: 0.7rem; font-weight: 600; color: var(--violet-dark);
}

/* Colour key, below the grid. It's lifted out of the flow into the card's own
   bottom padding, so it claims no row of its own and only its ink fades —
   revealing it never resizes the card or shifts anything below it. Invisible
   until the pointer is over the grid: a glanceable reference, not permanent
   chrome. Revealing on :hover of the legend too keeps it up while you read it. */
.cal-legend {
  margin: 14px 0 0; padding-top: 12px;
  border-top: 1px solid var(--line);
}
.cal-legend[hidden] { display: none; }
/* The fold control. `list-style: none` (plus the WebKit pseudo-element) drops
   the native triangle so we can draw our own, which rotates with the state. */
.legend-toggle {
  list-style: none; cursor: pointer; width: fit-content;

