import { chromium } from "playwright";

const out = "/tmp/claude-0/-home-user-EdFringeNow/baec1c64-532f-5d73-b7d5-d6ef365a9474/scratchpad";
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1500, height: 1000 }, deviceScaleFactor: 2 });
page.on("console", (m) => { if (m.type() === "error") console.log("CONSOLE ERR:", m.text()); });
page.on("pageerror", (e) => console.log("PAGE ERR:", e.message));

await page.goto("http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8899/plan/", { waitUntil: "networkidle" });

// Populate the grid via the debug "add random shows" control.
const btn = page.locator("#debugRandomBtn");
if (await btn.count()) {
  const opener = page.locator("[data-debug-toggle], .debug-pill, #debugPill").first();
  if (await opener.count()) await opener.click({ force: true }).catch(() => {});
  await btn.click({ force: true });
  await btn.click({ force: true });
} else {
  console.log("no debug button found");
}
await page.waitForTimeout(2500);

const gold = await page.locator(".seg--selected").count();
console.log("gold marks:", gold);
const phase = await page.evaluate(() => {
  const s = document.querySelector(".seg--selected");
  if (!s) return null;
  const cs = getComputedStyle(s, "::before");
  return {
    lane: getComputedStyle(s.closest(".lane")).getPropertyValue("--sheen-lane"),
    col: getComputedStyle(s.parentElement).getPropertyValue("--sheen-col"),
    delay: cs.animationDelay, name: cs.animationName, dur: cs.animationDuration,
    pos: cs.backgroundPosition,
  };
});
console.log("computed:", JSON.stringify(phase));

const cal = page.locator("#calPanel, .cal-wrap").first();
for (let i = 0; i < 4; i++) {
  await cal.screenshot({ path: `${out}/grid-${i}.png` });
  await page.waitForTimeout(400);
}
await browser.close();

