import { chromium } from "playwright";
const out = ".";
const b = await chromium.launch();

async function load(page) {
  await page.goto("http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8899/plan/", { waitUntil: "domcontentloaded" });
  const btn = page.locator("#debugRandomBtn");
  await page.locator("#debugPill").click();
  await btn.waitFor({ state: "visible" });
  await btn.click();
  await page.waitForTimeout(1200);
}

// 1. reduced motion
const rm = await b.newPage({ reducedMotion: "reduce", viewport: { width: 1400, height: 900 } });
await load(rm);
console.log("reduced-motion ::before =", await rm.evaluate(() => {
  const s = document.querySelector(".seg--selected");
  const cs = getComputedStyle(s, "::before");
  return { name: cs.animationName, opacity: cs.opacity };
}));

// 2. pinned mark: badge must still escape the bar upward (not clipped)
const p = await b.newPage({ viewport: { width: 1400, height: 900 }, deviceScaleFactor: 2 });
await load(p);
await p.locator(".seg--selected").first().click();
await p.waitForTimeout(800);
console.log("pin check =", await p.evaluate(() => {
  const seg = document.querySelector(".seg--pinned");
  if (!seg) return "no pinned seg";
  const badge = seg.querySelector(".seg-pin");
  if (!badge) return "no badge";
  const sb = seg.getBoundingClientRect(), bb = badge.getBoundingClientRect();
  const cs = getComputedStyle(seg, "::before");
  return { badgeAboveBar: bb.top < sb.top, badgeH: Math.round(bb.height),
           beforeAnim: cs.animationName, beforeDelay: cs.animationDelay };
}));
const cell = p.locator(".cell--pin").first();
await cell.screenshot({ path: `${out}/pinned.png` });

// 3. hover tooltip swatch
await p.locator(".seg--selected").first().hover();
await p.waitForTimeout(700);
const tip = p.locator("#calTip");
if (await tip.isVisible()) await tip.screenshot({ path: `${out}/tip.png` });
else console.log("tip not visible");
await b.close();
EOF
